#!/usr/bin/env node
// Mirrors published LinkedIn posts from the private jc-linkedin repo into
// src/content/activity/linkedin/. Runs locally only: CI cannot read jc-linkedin,
// so the generated files are committed. Never touches src/content/activity/manual/.
//
//   npm run sync                 # default source: ~/github_repositories/jc-linkedin
//   JC_LINKEDIN_DIR=/path npm run sync
import { readdir, readFile, writeFile, mkdir, unlink } from 'node:fs/promises';
import { homedir } from 'node:os';
import { join } from 'node:path';
import matter from 'gray-matter';

const SRC = join(process.env.JC_LINKEDIN_DIR ?? join(homedir(), 'github_repositories/jc-linkedin'), 'drafts/linkedin');
const OUT = new URL('../src/content/activity/linkedin/', import.meta.url).pathname;
const HEADER = '<!-- GENERATED by scripts/sync-activity.mjs. Do not edit: edit the source in jc-linkedin. -->';

const PERFILES = new Set(['profesor', 'investigador', 'experto']);
const PILARES = new Set(['metodologico', 'tematico', 'investigacion', 'reflexion']);

const isoDate = (v) => {
  if (v instanceof Date && !isNaN(v)) return v.toISOString().slice(0, 10);
  if (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v.trim())) return v.trim();
  return null;
};

// The post body ends at the first "## " heading; what follows is production material.
function cleanBody(raw) {
  const noComments = raw.replace(/<!--[\s\S]*?-->/g, '');
  const cut = noComments.search(/^##\s/m);
  return (cut >= 0 ? noComments.slice(0, cut) : noComments).trim();
}

function deriveTitle(body) {
  const first = body.split('\n').map((l) => l.trim()).find(Boolean) ?? '';
  const plain = first.replace(/[*_`#>]/g, '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').trim();
  if (plain.length <= 90) return plain;
  const cut = plain.slice(0, 90);
  return `${cut.slice(0, cut.lastIndexOf(' ')).replace(/[,;:.\s]+$/, '')}…`;
}

const files = (await readdir(SRC)).filter((f) => f.endsWith('.md')).sort();
await mkdir(OUT, { recursive: true });

const written = new Set();
const skipped = [];
const problems = [];
let created = 0;
let updated = 0;

for (const file of files) {
  const { data, content } = matter(await readFile(join(SRC, file), 'utf8'));
  if (data.canal && data.canal !== 'linkedin') continue;
  if (data.estado !== 'publicado') continue;
  const date = isoDate(data.publicado);
  if (!date) { skipped.push(`${file} (published without a date)`); continue; }

  const body = cleanBody(content);
  const lang = data.idioma;
  if (!body) { problems.push(`${file}: empty body after cleaning`); continue; }
  if (lang !== 'es' && lang !== 'en') { problems.push(`${file}: idioma "${lang}" is not es|en`); continue; }

  const fm = { title: deriveTitle(body), date, lang, source: 'linkedin' };
  if (PERFILES.has(data.perfil)) fm.perfil = data.perfil;
  if (PILARES.has(data.pilar)) fm.pilar = data.pilar;
  if (typeof data.url === 'string' && data.url.startsWith('https://')) fm.url = data.url;
  fm.sourceFile = file;
  fm.generated = true;

  const out = `${matter.stringify(`${HEADER}\n\n${body}\n`, fm).trim()}\n`;
  const target = join(OUT, file);
  const previous = await readFile(target, 'utf8').catch(() => null);
  if (previous === null) created++;
  else if (previous !== out) updated++;
  if (previous !== out) await writeFile(target, out);
  written.add(file);
}

let removed = 0;
for (const f of await readdir(OUT)) {
  if (f.endsWith('.md') && !written.has(f)) { await unlink(join(OUT, f)); removed++; }
}

console.log(`sync-activity: ${written.size} published posts · ${created} new · ${updated} updated · ${removed} removed`);
for (const s of skipped) console.log(`  skipped: ${s}`);
if (problems.length) {
  for (const p of problems) console.error(`  ERROR: ${p}`);
  process.exit(1);
}
